            }
            if (importListResource.RootFolderPathOption.IsSet)
                if (importListResource.RootFolderPathOption.Value != null)
                    writer.WriteString("rootFolderPath", importListResource.RootFolderPath);
                else
                    writer.WriteNull("rootFolderPath");

            if (importListResource.QualityProfileIdOption.IsSet)
                writer.WriteNumber("qualityProfileId", importListResource.QualityProfileIdOption.Value!.Value);

            if (importListResource.SearchOnAddOption.IsSet)
                writer.WriteBoolean("searchOnAdd", importListResource.SearchOnAddOption.Value!.Value);

            if (importListResource.ListTypeOption.IsSet)
            {
                var listTypeRawValue = ImportListTypeValueConverter.ToJsonValue(importListResource.ListType!.Value);
                writer.WriteString("listType", listTypeRawValue);
            }
            if (importListResource.ListOrderOption.IsSet)
                writer.WriteNumber("listOrder", importListResource.ListOrderOption.Value!.Value);

            if (importListResource.MinRefreshIntervalOption.IsSet)
                writer.WriteString("minRefreshInterval", importListResource.MinRefreshInterval);

            if (importListResource.LastInfoSyncOption.IsSet)
                if (importListResource.LastInfoSyncOption.Value != null)
                    writer.WriteString("lastInfoSync", importListResource.LastInfoSyncOption.Value!.Value.ToString(LastInfoSyncFormat));
                else
                    writer.WriteNull("lastInfoSync");
        }
    }
}
